"""Three original short poems and two independent stories for early literary reading."""
def author(E,C,O,A,D):
 E('plan-G1-literature-07','S2','A','여러 곳에서 들리는 같은 말',
 '시: 빗방울의 인사\n우산 끝에서 똑똑\n신발 코에서도 똑똑\n누가 문을 두드리나\n빗방울이 나를 따라와\n집 앞까지 똑똑 똑똑',
 '종이에 반복된 말을 찾는 활동이다. 실제 소리 듣기나 낭송 수행을 했다고 집계하지 않는다. 반복되는 말만 짧게 인용하면 여러 행에 겹치므로 행의 대상을 함께 확인한다.',[
 A('evidence_selection','같은 소리 말이 나온 서로 다른 두 곳을 시에서 찾아 쓰세요.','우산 끝에서 똑똑 / 신발 코에서도 똑똑. 집 앞의 행을 대신 골라도 수용한다.',['우산 끝에서 똑똑','신발 코에서도 똑똑'],[D('반복 말 찾기','똑똑이 여러 곳에 쓰였음을 찾는다.','한 곳만 찾거나 반복 말의 일부만 짚는다.','반복되지 않은 말만 고른다.'),D('두 위치 구별','우산·신발·집 앞 가운데 서로 다른 두 위치와 소리 말을 함께 제시한다.','두 번 적었지만 같은 행만 되풀이한다.','시와 관계없는 두 장소를 새로 쓴다.')]),
 C('여러 행에서 되풀이한 말은 무엇인가요?','똑똑','우산과 신발, 집 앞에서 같은 말이 되풀이된다.',[('우산','우산은 한 행의 대상이다.'),('신발','신발은 한 행에 나온 대상이다.')],['우산 끝에서 똑똑','집 앞까지 똑똑 똑똑']),
 O('matching','우산 끝 / 신발 코 / 집 앞을 각각의 행에서 찾아 짚으세요.','우산 끝:첫 행 / 신발 코:둘째 행 / 집 앞:마지막 행. 행 번호 대신 해당 구절을 그대로 찾아도 수용한다.',['우산 끝에서','신발 코에서도','집 앞까지'],'세 곳 중 두 곳만 찾음','장소를 서로 바꾸거나 없는 행을 제시함'),
 O('explanation','똑똑이 되풀이되니 어떤 소리나 모습이 떠오르나요? 시의 한 곳과 함께 말이나 글로 남기세요.','우산과 신발을 지나 집 앞까지 빗소리가 계속 따라오는 것 같다. 다른 근거 있는 느낌도 수용한다.','빗방울이 나를 따라와','느낌만 쓰고 시의 구절과 연결하지 못함','시와 관계없는 기계 소리만 떠올렸다고 함')],
 [('시: 빗방울의 인사',5)])
 E('plan-G1-literature-07','S3','A','통통과 살금살금',
 '시 가: 공을 따라\n통통, 공이 마당을 건너요\n통통, 내 발도 공을 따라요\n담장 앞에서 돌아서\n다시 통통, 우리 집으로\n시 나: 고양이 곁에서\n살금살금 고양이 곁으로\n살금살금 작은 그림자\n나는 한 발 멈추고\n바람도 살금살금 기다려요',
 '같은 말의 반복이 각 시에서 어떤 움직임과 연결되는지 본다. 통통은 언제나 기쁨, 살금살금은 언제나 무서움이라는 감정 정답을 만들지 않는다.',[
 A('explanation','두 시의 반복 말과 움직임을 각각 이어 보세요. 어떤 모습이 다르게 떠오르나요?','가의 통통은 공과 발이 계속 움직이는 모습을, 나의 살금살금은 고양이 곁에서 조심히 가다 멈추는 모습을 떠올리게 한다. 다른 근거 있는 비교도 수용한다.',['통통, 내 발도','나는 한 발 멈추고'],[D('말과 대상','가의 통통과 나의 살금살금을 각각의 장면에 맞게 잇는다.','한 시의 말과 대상만 잇는다.','두 시의 반복 말을 서로 바꾼다.'),D('움직임 비교','공·발의 움직임과 조심히 가거나 멈춘 모습의 차이를 구절과 연결한다.','다르다고만 하거나 느낌 한 낱말만 쓴다.','반복 말만으로 인물의 마음을 하나로 확정한다.')]),
 C('반복 말을 두 시에 맞게 이은 것은 무엇인가요?','가:통통 / 나:살금살금','가에서는 공과 발, 나에서는 고양이 곁과 그림자에 연결된다.',[('가:살금살금 / 나:통통','두 시의 말을 바꾸었다.'),('가:똑똑 / 나:사각사각','두 시에 없는 소리 말을 골랐다.')],['통통, 공이','살금살금 작은']),
 O('evidence_selection','나에서 움직임을 멈추는 행을 찾으세요.','나는 한 발 멈추고','나는 한 발 멈추고','멈춘다고만 적고 해당 행을 찾지 못함','통통 공의 행을 고름'),
 O('explanation','한 시를 골라 반복 말을 한 번만 남긴다면 읽는 느낌이 어떻게 달라질지 짐작해 보세요.','예:가에서 통통을 한 번만 쓰면 집으로 돌아갈 때까지 계속 튀는 느낌이 덜할 수 있다. 다른 타당한 비교도 수용한다.','다시 통통, 우리 집으로','달라진다고만 하고 반복과 장면의 관계가 없음','반복을 줄이면 시의 모든 내용이 반드시 반대가 된다고 함')],
 [('시 가: 공을 따라',4),('시 나: 고양이 곁에서',4)])
 E('plan-G2-literature-04','S3','A','긴 목도리의 끝',
 '해솔은 정류장 지붕 아래서 손을 비볐다. 소라의 목에는 긴 목도리가 두 번 감겨 있었다. 해솔이 “목도리 따뜻하겠다.” 하고 말하자 소라는 “난 괜찮아.”라고 했다. 그러고는 목도리 한 바퀴를 풀었다.\n해솔은 소라가 목도리를 벗으려나 하고 생각했다. 그런데 소라는 풀린 끝을 해솔의 어깨 쪽으로 내밀었다. 해솔이 “너도 춥지 않아?” 하고 묻자 소라는 “우리 목도리 길잖아.”라고 말했다.\n두 사람은 긴 끝을 나누어 두르고 지붕의 안쪽으로 한 걸음 옮겼다. 목도리 한가운데가 두 사람 사이에서 살짝 처졌다. 버스가 올 때까지 해솔은 소라와 나란히 서 있었다.',
 '괜찮다는 한마디만으로 소라가 전혀 춥지 않았다고 확정하지 않는다. 말 뒤의 목도리 풀기·내밀기·함께 두르기를 연결해 이해한다.',[
 A('explanation','소라의 난 괜찮아와 우리 목도리 길잖아를 행동과 함께 읽으면 어떤 뜻으로 이해할 수 있나요? 두 행동을 근거로 설명하세요.','목도리를 자기만 두르기보다 해솔과 함께 나누어 쓰려는 뜻으로 읽을 수 있다. 한 바퀴를 풀어 끝을 해솔에게 내밀고 둘이 나누어 둘렀기 때문이다. 다른 근거 있는 해석도 수용한다.',['목도리 한 바퀴를 풀었다.','해솔의 어깨 쪽으로 내밀었다.'],[D('말·행동의 연결','두 말을 목도리를 나누는 행동과 연결해 설명한다.','함께 쓴다는 결과만 말하고 말의 뜻과 연결이 약하다.','말만 보고 소라가 목도리를 버리려 했다고 확정한다.'),D('구체적 근거','풀기·내밀기·함께 두르기 중 서로 이어지는 두 행동을 근거로 든다.','한 행동만 제시한다.','작품에 없는 선물 구입이나 다툼을 근거로 든다.')]),
 C('함께 쓰려는 행동을 직접 보여 주는 부분은 무엇인가요?','풀린 끝을 해솔의 어깨 쪽으로 내밀었다.','자기에게만 두르지 않고 친구 쪽으로 내미는 행동이다.',[('목에 목도리를 두 번 감고 서 있었다.','처음 자기 목에 두른 상태만 보여 주며 함께 쓰는 행동은 아직 아니다.'),('해솔이 목도리가 따뜻하겠다고 말했다.','해솔의 말이며 소라가 함께 쓰도록 한 행동 자체는 아니다.')],'해솔의 어깨 쪽으로 내밀었다.'),
 O('ordering','한 바퀴 풀기 / 둘이 나누어 두르기 / 끝을 내밀기를 차례대로 쓰세요.','한 바퀴 풀기 → 끝을 내밀기 → 둘이 나누어 두르기',['한 바퀴를 풀었다.','긴 끝을 나누어 두르고'],'중간 행동을 빠뜨림','함께 두른 뒤 처음 목도리를 풀었다고 씀'),
 O('explanation','괜찮다는 말만으로 소라가 전혀 춥지 않았다고 확정하기 어려운 이유를 쓰세요.','그 말은 함께 쓰려는 상황에서 한 말일 수 있고 소라의 실제 추위 정도를 따로 알려 주지는 않기 때문이다.','난 괜찮아','모른다고만 하고 말이 나온 상황을 짚지 못함','인물이 괜찮다고 말하면 언제나 속마음과 몸 상태를 모두 알 수 있다고 함')])
 E('plan-G2-literature-04','S4','A','잠깐 비워 둔 자리',
 '다온은 아람 옆에 앉아 작은 종이 인형을 색칠하고 있었다. 아람은 책상 아래 상자를 꺼내더니 “그 자리 잠깐 비워 줄래?”라고 말했다. 다온은 색연필을 챙겨 벽 쪽으로 옮겼다. 종이 인형도 가슴 앞에 꼭 들었다.\n아람은 상자에서 긴 종이를 꺼냈다. 접힌 종이는 다온이 앉았던 자리까지 펼쳐졌다. 아람은 종이 한쪽에 나무를 그리고 반대쪽에는 창문 모양을 붙였다. 가운데는 비워 두었다.\n다온은 벽 쪽에서 그 모습을 보다가 작은 인형을 내려다보았다. 어제 아람과 “이 인형이 살 집은 어떤 모양일까?” 하고 이야기했던 것이 생각났다. 아람은 긴 종이를 조금 밀어 가운데 빈 곳이 다온 앞에 오게 했다. 그러고는 다온의 인형과 빈 곳을 번갈아 보며 손바닥을 폈다.\n다온은 아까 챙긴 색연필을 다시 책상에 놓았다. 작은 인형을 긴 종이 가운데에 세우자 창문이 인형의 얼굴 높이에 닿았다.',
 '잠깐 비워 달라는 말을 배제로 단정한 해석을 행동·앞선 대화와 대조한다. 아람의 모든 속마음을 정확히 안다는 정답은 요구하지 않는다.',[
 A('explanation','아람이 자리를 비워 달라고 한 말의 뜻을 뒤의 행동과 연결해 짐작하세요. 다온이 돌아온 까닭도 함께 설명해 보세요.','긴 종이를 펼쳐 인형이 설 집이나 무대를 만들 공간이 필요했던 것으로 읽을 수 있다. 아람이 어제의 집 이야기에 맞는 창문을 붙이고 빈 곳을 다온에게 밀어 주자 다온도 함께할 자리라고 이해했을 수 있다. 다른 근거 있는 짐작도 수용한다.',['그 자리 잠깐 비워 줄래','가운데 빈 곳이 다온 앞에','창문이 인형의 얼굴 높이'],[D('말의 재해석','자리 비우기를 긴 종이를 펼칠 필요와 뒤의 참여 행동을 연결해 짐작한다.','나쁜 뜻은 아니라고만 하고 이유를 설명하지 못한다.','처음 한마디만으로 끝까지 친구를 내쫓으려 했다고 확정한다.'),D('근거의 연결','긴 종이·앞선 집 대화·빈 곳 밀어 주기·인형 세우기 중 두 단서 이상을 잇는다.','한 단서만 들거나 사건 순서가 흐리다.','작품에 없는 사과·다툼·새 인형 선물을 근거로 든다.')]),
 C('아람이 다온에게 참여할 공간을 내미는 행동은 무엇인가요?','가운데 빈 곳이 다온 앞에 오도록 종이를 밀었다.','다온의 인형과 빈 공간을 이어 보며 내민 행동은 참여할 자리라는 해석을 지지한다.',[('다온이 색연필을 챙겨 벽 쪽으로 옮겼다.','처음의 다온 행동이며 아람이 참여 공간을 내민 행동은 아니다.'),('아람이 먼저 책상 아래에서 상자를 꺼냈다.','준비를 시작한 행동이지만 다온에게 공간을 내민 구체적 행동과는 다르다.')],'가운데 빈 곳이 다온 앞에'),
 O('evidence_selection','창문 높이가 인형과 어울린다는 것을 보여 주는 마지막 장면을 찾으세요.','창문이 인형의 얼굴 높이에 닿았다.','창문이 인형의 얼굴 높이','창문만 짚고 인형과의 관계가 없음','벽 쪽으로 옮겼다는 처음 장면만 고름'),
 O('explanation','아람의 처음 말이 다온에게 다르게 들릴 수 있었다면 어떤 말을 더하면 오해가 줄었을지 상상하고 작품과 연결해 설명하세요.','긴 종이를 펼쳐 네 인형이 설 곳을 만들려고 잠깐 자리가 필요해라고 덧붙이면 좋겠다. 긴 종이와 앞선 집 이야기에서 생각한 말이다. 다른 근거 있는 표현도 수용한다.',['접힌 종이는 다온이 앉았던','인형이 살 집은 어떤'],'보탤 말은 있지만 작품 상황과의 관계를 설명하지 못함','보탠 말을 원래 인물이 실제로 했다고 주장함')])
